const audit_id = $('Update Status Crawling').first().json.body ? $('Update Status Crawling').first().json.body[0].id : ($('Webhook').first().json.body ? $('Webhook').first().json.body.audit_id : null);
const url = $('Webhook').first().json.body ? $('Webhook').first().json.body.url : null;
if (!audit_id || !url) throw new Error('Missing audit_id or url');

const base_url = url.replace(/\/+$/, '');
const parsed = new URL(base_url);
const origin = parsed.origin;

const KEY_PATHS = ['/', '/about', '/about-us', '/services', '/products', '/pricing', '/contact', '/booking'];
let discovered = [];

try {
  const sitemapUrl = origin + '/sitemap.xml';
  const resp = await fetch(sitemapUrl, { signal: AbortSignal.timeout(5000) });
  if (resp.ok) {
    const xml = await resp.text();
    const locMatches = xml.match(/<loc>\s*<\/loc>/gi) || [];
    for (const m of locMatches) {
      const loc = m.replace(/<loc>\s*/i, '').replace(/\s*<\/loc>/i, '').trim();
      try {
        const u = new URL(loc);
        if (u.origin === origin) {
          discovered.push(u.pathname);
        }
      } catch {}
    }
  }
} catch {}

const allPaths = [...new Set([...KEY_PATHS, ...discovered])];
const selected = allPaths.slice(0, 10);

return selected.map(p => ({
  json: {
    audit_id,
    base_url: origin,
    path: p,
    full_url: origin + p
  }
}));

const page = $input.first().json;
const url = page.full_url;
if (!url) throw new Error('No URL to crawl');

let html = '';
try {
  const resp = await fetch(url, {
    signal: AbortSignal.timeout(15000),
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; AuditBot/1.0)' }
  });
  if (!resp.ok) throw new Error('HTTP ' + resp.status);
  html = await resp.text();
} catch (e) {
  return [{ json: { ...page, error: e.message, crawled_at: new Date().toISOString() } }];
}

function extract(tag, attr) {
  const re = new RegExp('<' + tag + '[^>]*' + attr + '=\"([^\"]*?)\"', 'gi');
  const m = re.exec(html);
  return m ? m[1].trim() : '';
}

function extractMeta(name) {
  const re = new RegExp('<meta[^>]+name=\"' + name + '\"[^>]+content=\"([^\"]*?)\"', 'gi');
  const m = re.exec(html);
  return m ? m[1].trim() : '';
}

const title = extract('title', '').replace(/<[^>]+>/g, '').trim() || extract('title', '');
const meta_description = extractMeta('description');
const viewport = extract('meta', 'name') === 'viewport' ? extract('meta', 'content') : '';
const canonical = extract('link', 'rel') === 'canonical' ? extract('link', 'href') : '';

const formRe = /<form[^>]*>/gi;
const forms = [];
let fm;
while ((fm = formRe.exec(html)) !== null) {
  const tag = fm[0];
  const action = (tag.match(/action=\"([^\"]*?)\"/) || [])[1] || '';
  const method = (tag.match(/method=\"([^\"]*?)\"/) || [])[1] || 'GET';
  const inputCount = (html.slice(fm.index).match(/<input[^>]*>/gi) || []).length;
  forms.push({ action, method, input_count: inputCount });
}

const linkRe = /<a[^>]+href=\"([^\"]*?)\"[^>]*>/gi;
const links = [];
let lm;
while ((lm = linkRe.exec(html)) !== null) {
  links.push(lm[1]);
}

const imgRe = /<img[^>]*>/gi;
const images = [];
let im;
while ((im = imgRe.exec(html)) !== null) {
  const tag = im[0];
  const alt = tag.match(/alt=\"([^\"]*?)\"/);
  images.push({ has_alt: !!alt && alt[1].length > 0 });
}

const h1Count = (html.match(/<h1[^>]*>/gi) || []).length;
const h2Count = (html.match(/<h2[^>]*>/gi) || []).length;

const TECH_FINGERPRINTS = {
  'WordPress': /wp-content|wp-includes|wordpress/i,
  'Shopify': /shopify|cdn\.shopify\.com/i,
  'Calendly': /calendly\.com|calendly\.js/i,
  'Jotform': /jotform\.com|jotform\.js/i,
  'Typeform': /typeform\.com|typeform\.js/i,
  'HubSpot': /hubspot|hs-scripts|hs-scripts\.com/i,
  'Google Analytics': /google-analytics\.com|gtag|ga\.js|analytics\.js/i,
  'Google Tag Manager': /googletagmanager\.com|gtm\.js/i,
  'Intercom': /intercom\.com|intercomcdn/i,
  'Zendesk': /zendesk\.com|zdassets\.com/i,
  'Stripe': /stripe\.com|js\.stripe\.com/i,
  'PayPal': /paypal\.com|paypalobjects\.com/i,
  'WhatsApp': /whatsapp\.com|wa\.me|api\.whatsapp\.com/i,
  'Next.js': /_next\/|next\.js/i,
  'React': /react|reactdom|__next/i,
  'Mailchimp': /mailchimp|list-manage\.com|mc\.us/i,
  'Klaviyo': /klaviyo\.com|klaviyo\.js/i,
  'Webflow': /webflow\.com|wf-cdn/i
};

const technologies = [];
for (const [name, re] of Object.entries(TECH_FINGERPRINTS)) {
  if (re.test(html)) technologies.push(name);
}

const images_no_alt = images.filter(i => !i.has_alt).length;

return [{
  json: {
    ...page,
    title,
    meta_description,
    viewport_tag: viewport,
    canonical_tag: canonical,
    forms,
    links_count: links.length,
    images_total: images.length,
    images_no_alt,
    h1_count: h1Count,
    h2_count: h2Count,
    technologies,
    crawled_at: new Date().toISOString()
  }
}];

