const input = $input.first().json;
const content = input && input.choices && input.choices[0]
  ? (input.choices[0].message && input.choices[0].message.content) || input.choices[0].text
  : null;
if (!content) throw new Error('DeepSeek returned no content: ' + JSON.stringify(input).slice(0, 500));
let cleaned = String(content).trim();
const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (fenced) cleaned = fenced[1].trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('DeepSeek analysis response is not JSON: ' + cleaned.slice(0, 500));
}
const issues = Array.isArray(parsed.issues) ? parsed.issues : [];
const VALID_CATEGORIES = ['ux', 'ui', 'performance', 'accessibility', 'seo', 'conversion'];
const VALID_SEVERITIES = ['critical', 'high', 'medium', 'low'];
const validated = issues.map(issue => ({
  category: VALID_CATEGORIES.includes(issue.category) ? issue.category : 'other',
  severity: VALID_SEVERITIES.includes(issue.severity) ? issue.severity : 'medium',
  title: String(issue.title || 'Untitled'),
  description: String(issue.description || ''),
  evidence: String(issue.evidence || ''),
  recommendation: String(issue.recommendation || ''),
  classification: 'observed'
}));
return { issues: validated };

const pages = $('Save Page').all().map(i => i.json);
const issues = $('Parse AI Analysis').first().json.issues;
const audit_id = $('Update Status Crawling').first().json.body ? $('Update Status Crawling').first().json.body[0].id : $('Webhook').first().json.body.audit_id;

const allTech = [...new Set(pages.flatMap(p => p.technologies || []))];

let seo_total = 10, seo_issues = 0;
let accessibility_total = 10, accessibility_issues = 0;
let performance_total = 10, performance_issues = 0;
let ui_total = 10, ui_issues = 0;
let ux_total = 10, ux_issues = 0;
let conversion_total = 10, conversion_issues = 0;

for (const issue of issues) {
  const penalty = issue.severity === 'critical' ? 3 : issue.severity === 'high' ? 2 : issue.severity === 'medium' ? 1 : 0.5;
  if (issue.category === 'seo') { seo_issues += penalty; seo_total -= penalty; }
  if (issue.category === 'accessibility') { accessibility_issues += penalty; accessibility_total -= penalty; }
  if (issue.category === 'performance') { performance_issues += penalty; performance_total -= penalty; }
  if (issue.category === 'ui') { ui_issues += penalty; ui_total -= penalty; }
  if (issue.category === 'ux') { ux_issues += penalty; ux_total -= penalty; }
  if (issue.category === 'conversion') { conversion_issues += penalty; conversion_total -= penalty; }
}

const clamp = v => Math.max(0, Math.min(10, Math.round(v * 10) / 10));
const seo_score = clamp(seo_total);
const accessibility_score = clamp(accessibility_total);
const performance_score = clamp(performance_total);
const ui_score = clamp(ui_total);
const ux_score = clamp(ux_total);
const conversion_score = clamp(conversion_total);

const overall_score = clamp(
  seo_score * 0.20 +
  accessibility_score * 0.15 +
  performance_score * 0.20 +
  ui_score * 0.15 +
  ux_score * 0.15 +
  conversion_score * 0.15
);

const hasBooking = allTech.some(t => ['Calendly', 'Typeform'].includes(t));
const hasCRM = allTech.some(t => ['HubSpot', 'Intercom'].includes(t));
const hasForms = pages.some(p => (p.forms || []).length > 0);
const automation_score = clamp(
  (hasBooking ? 3 : 0) +
  (hasCRM ? 3 : 0) +
  (hasForms ? 2 : 0) +
  (allTech.includes('Google Analytics') ? 1 : 0) +
  (allTech.includes('Google Tag Manager') ? 1 : 0)
);

return [{
  json: {
    audit_id,
    ui_score,
    ux_score,
    performance_score,
    accessibility_score,
    seo_score,
    conversion_score,
    overall_score,
    automation_score,
    all_technologies: allTech
  }
}];

const input = $input.first().json;
const content = input && input.choices && input.choices[0]
  ? (input.choices[0].message && input.choices[0].message.content) || input.choices[0].text
  : null;
if (!content) throw new Error('DeepSeek returned no content: ' + JSON.stringify(input).slice(0, 500));
let cleaned = String(content).trim();
const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (fenced) cleaned = fenced[1].trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('DeepSeek opportunities response is not JSON: ' + cleaned.slice(0, 500));
}
const opportunities = Array.isArray(parsed.opportunities) ? parsed.opportunities : [];
const VALID_CATEGORIES = ['lead_capture', 'appointment', 'crm', 'ecommerce', 'email', 'whatsapp', 'support', 'quote', 'internal_workflow', 'ai_agent', 'seo', 'performance', 'ui_ux', 'other'];
const VALID_IMPACT = ['high', 'medium', 'low'];
const VALID_AUTOMATION = ['high', 'medium', 'low'];
const VALID_COMPLEXITY = ['simple', 'moderate', 'complex'];
const validated = opportunities.map(opp => ({
  title: String(opp.title || 'Untitled'),
  category: VALID_CATEGORIES.includes(opp.category) ? opp.category : 'other',
  observed_signal: String(opp.observed_signal || ''),
  evidence: String(opp.evidence || ''),
  inference: String(opp.inference || ''),
  confidence: Math.max(0, Math.min(1, Number(opp.confidence) || 0.5)),
  business_impact: VALID_IMPACT.includes(opp.business_impact) ? opp.business_impact : 'medium',
  automation_potential: VALID_AUTOMATION.includes(opp.automation_potential) ? opp.automation_potential : 'medium',
  estimated_complexity: VALID_COMPLEXITY.includes(opp.estimated_complexity) ? opp.estimated_complexity : 'moderate',
  recommended_tools: Array.isArray(opp.recommended_tools) ? opp.recommended_tools : [],
  recommended_workflow: String(opp.recommended_workflow || ''),
  implementation_notes: String(opp.implementation_notes || ''),
  outreach_angle: String(opp.outreach_angle || ''),
  score: Math.max(0, Math.min(100, Number(opp.score) || 50))
}));
return { opportunities: validated };
